\u0024\u0070\u0067\u007e\u0067\u002e\u005e\u0041\u0021\u004a\u002b\u0038\u0031\u0064\u005f\u0071\u0078\u0021\u006c\u0056\u0078\u0030\u0059\u0075\u0059\u0023\u0060\u0071\u0063\u0064\u0028\u0078\u002c\u0021\u0042\u0059\u007c\u005d\u0032\u0061\u004c\u002f\u0023\u0050\u006e\u0051\u0021\u0029\u004f\u006f\u006f\u004c\u006c\u0025\u0076\u0066\u006b\u0029\u0055\u003b\u0064\u005d\u0050\u0060\u006d\u005e\u0033\u0046\u0073\u0042\u0068\u0050\u0039\u0032\u002f\u0052\u0067\u0034\u006f\u003a\u0079\u0057\u0071\u005e\u0022\u0064\u003d\u0032\u0067\u007c\u0038\u003f\u0058\u0067\u0041\u003f\u007c\u0063\u006f\u0038\u0073\u0052\u0030\u0047\u0035\u002b\u0064\u0021\u0077\u0026\u0051\u0043\u0032\u006b\u0039\u0049\u006d\u0025\u0034\u0046\u0063\u0021\u0043\u004e\u0065\u005d\u0078\u006c\u0078\u0052\u0077\u0054\u004b\u0066\u0041\u0021\u0073\u0050\u002b\u0021\u0079\u0071\u0065\u0060\u0023\u0045\u004d\u0067\u0040\u004e\u0051\u0033\u0064\u0053\u0055\u005e\u006c\u002e\u0077\u006a\u006b\u005e\u004f\u0060\u0047\u006f\u007a\u0076\u0034\u0046\u0063\u0021\u0036\u0029\u0024\u0079\u0073\u0030\u0024\u0064\u0053\u0055\u0054\u0074\u0067\u0063\u0050\u007d\u0071\u005f\u0063\u0058\u002a\u003f\u004f\u0074\u0073\u0033\u0052\u004f\u0070\u006e\u007b\u0076\u005f\u003f\u006c\u002a\u0051\u005d\u0067\u0072\u0073\u0047\u0036\u006f\u0060\u0023\u0055\u006b\u003f\u0021\u0030\u003c\u002b\u0050\u0062\u006d\u0024\u0047\u0068\u0051\u0062\u0033\u006b\u0043\u0026\u0053\u0077\u005f\u003b\u0021\u0072\u0023\u0034\u0037\u006e\u0079\u003e\u0052\u005f\u0041\u007c\u0067\u0071\u0035\u005f\u0076\u0076\u0037\u0033\u005b\u0039\u0073\u0076\u007a\u0022\u0022\u0065\u0058\u0024\u004d\u0021\u0064\u0042\u0031\u0031\u0052\u0048\u005a\u0022\u004b\u0046\u0021\u0051\u003f\u005a\u0054\u0072\u004c\u002a\u0024\u0033\u0038\u0032\u002c\u006f\u0074\u0064\u005a\u0062\u003f\u003b\u0044\u0046\u0021\u005f\u0038\u002a\u007b\u0076\u0072\u003b\u003f\u0064\u004b\u0058\u002e\u003f\u0040\u0025\u0052\u0063\u0031\u0076\u003f\u0038\u0023\u004e\u0021\u005d\u006b\u006f\u004b\u003d\u007c\u002f\u0040\u0047\u0022\u0036\u0037\u003c\u0073\u0033\u0064\u006f\u004b\u0057\u002f\u0033\u0072\u0040\u006e\u0062\u0033\u0026\u003c\u005e\u0034\u0023\u0036\u0035\u004d\u0069\u0072\u003b\u0035\u002f\u0076\u0033\u006f\u0026\u0074\u0050\u0073\u0065\u0023\u0028\u0067\u0024\u003d\u0021\u0053\u006e\u006d\u0031\u007c\u0060\u0021\u006b\u006e\u0033\u003d\u0041\u003f\u006f\u0056\u0064\u0062\u0024\u0065\u0033\u005b\u004a\u0043\u007c\u0073\u0071\u0039\u0050\u003e\u0050\u0051\u007e\u0048\u0067\u0073\u0078\u006f\u0059\u0073\u0064\u002c\u0044\u003f\u003c\u002b\u003c\u0036\u0077\u0050\u0074\u0042\u002c\u003b\u007c\u002a\u0031\u0042\u0038\u0033\u0048\u0078\u0055\u0049\u0033\u0066\u0067\u004b\u0022\u0055\u0074\u0028\u0021\u0042\u006e\u0071\u002b\u003c\u0063\u005d\u0037\u0024\u0047\u0058\u0077\u0063\u0062\u0050\u007b\u007e\u0072\u0077\u004c\u0059\u0031\u004e\u0064\u0079\u0051\u0071\u0033\u0045\u0064\u0028\u0023\u0063\u003a\u0031\u0051\u0024\u003a\u0065\u006f\u0033\u0076\u0037\u003f\u0076\u0076\u003f\u0054\u002b\u0029\u0072\u004b\u005f\u007c\u006e\u0025\u002c\u0034\u0025\u0076\u006d\u0041\u0061\u0073\u005b\u004f\u0067\u0071\u0074\u0071\u0071\u006e\u0028\u0061\u002e\u007d\u003a\u0037\u005e\u0063\u004a\u0030\u0067\u0074\u002a\u0029\u0032\u0023\u0033\u0024\u005a\u004a\u0039\u0050\u005d\u0022\u0022\u002b\u0063\u0021\u0033\u0075\u005a\u0068\u0049\u0077\u0034\u006b\u004d\u0073\u006d\u0076\u0034\u0076\u0060\u0023\u0053\u0043\u0029\u0079\u003a\u0052\u0053\u006b\u0060\u0061\u006e\u003a\u0033\u0064\u0065\u0051\u006d\u0034\u005e\u0049\u002a\u0031\u003b\u0067\u0042\u0044\u0021\u0043\u0034\u0058\u0065\u0029\u004b\u0026\u004b\u0066\u0033\u003f\u0036\u0028\u0042\u0067\u007d\u0065\u003a\u0065\u003e\u0033\u0072\u003d\u0067\u0079\u0061\u006f\u0047\u0075\u0071\u007c\u0033\u0052\u0053\u004a\u0023\u0035\u004b\u0078\u005d\u0067\u004d\u0037\u002c\u0064\u0022\u0047\u0071\u0059\u0021\u0047\u0042\u0039\u0076\u0029\u0072\u0071\u0051\u002b\u0033\u005f\u0076\u0046\u0056\u0061\u0055\u0075\u005b\u003c\u0051\u0070\u0051\u0064\u0033\u0041\u004f\u0055\u005b\u006b\u006b\u004c\u003f\u0034\u004b\u007d\u0042\u0068\u0041\u0051\u007b\u0062\u0025\u007d\u0030\u0079\u002b\u0074\u0071\u0060\u0021\u0036\u0060\u007d\u0059\u007d\u0046\u003a\u0049\u0047\u0043\u0066\u003e\u002f\u0053\u0060\u0060\u0039\u002f\u0052\u0053\u0040\u0065\u007e\u0045\u0026\u0025\u002c\u0036\u0041\u0073\u003f\u0024\u0071\u0065\u0049\u0023\u007d\u005a\u0073\u005e\u005f\u0047\u0036\u0068\u0040\u0028\u0040\u0025\u0047\u0045\u004a\u005b\u0059\u0031\u0039\u0075\u007e\u005e\u0039\u0079\u005d\u0058\u006a\u0076\u0038\u0041\u004e\u0073\u006e\u003b\u003a\u0047\u006a\u002e\u0062\u0037\u0076\u003e\u0073\u0065\u007b\u006c\u003f\u0061\u0057\u006e\u0052\u002f\u0033\u005e\u0043\u0034\u004d\u0025\u0028\u005b\u0070\u0037\u0073\u004c\u005d\u002a\u003c\u006b\u0053\u0066\u002a\u0029\u0070\u0034\u006c\u0074\u002e\u0070\u0038\u006c\u003f\u007e\u0054\u007b\u002a\u002c\u0064\u002c\u0068\u0033\u007e\u0042\u0022\u0024\u0051\u0047\u0076\u005f\u0026\u003b\u0073\u0026\u005b\u0044\u0035\u0068\u0031\u0066\u0057\u0052\u007d\u0033\u0043\u0034\u003b\u0051\u0041\u0046\u004a\u006e\u006b\u0057\u0032\u004d\u003d\u0033\u0044\u0062\u0059\u0038\u005b\u0040\u005e\u0069\u0031\u0057\u0079\u005b\u0044\u007e\u006e\u0074\u003a\u0072\u006c\u006a\u0044\u0055\u0041\u0048\u0057\u0031\u007b\u007e\u006e\u002a\u0062\u006d\u0021\u0060\u0076\u007e\u0071\u0045\u003a\u005b\u0050\u002f\u0044\u006e\u0060\u0021\u007a\u003b\u0051\u0061\u0028\u0044\u0069\u0066\u0057\u004b\u0046\u0066\u0069\u004e\u0062\u006d\u005a\u006c\u0067\u0051\u0038\u0078\u0045\u005f\u007d\u0058\u0064\u0040\u002a\u0073\u0065\u0024\u002f\u006e\u005b\u0076\u006f\u0043\u005f\u004c\u0034\u007d\u0065\u003c\u0059\u007a\u0073\u0023\u0055\u003e\u0070\u0044\u0048\u0057\u0065\u006e\u0037\u0057\u005a\u0046\u003b\u0069\u0047\u0021\u003d\u0066\u0051\u0067\u007b\u0029\u0059\u0051\u005a\u007d\u006f\u0032\u003c\u0079\u0049\u0041\u007b\u0043\u0049\u0055\u0053\u0060\u0031\u0036\u004c\u0052\u0028\u0052\u0072\u0064\u0063\u003a\u0040\u003e\u002e\u0050\u003d\u0066\u0054\u004b\u004d\u0051\u0065\u0058\u0021\u006f\u0046\u003c\u006f\u0071\u0053\u0039\u0050\u0034\u003e\u0025\u0074\u0042\u005e\u0034\u0032\u006b\u004c\u0051\u0069\u0022\u0054\u0032\u0043\u0050\u0051\u0054\u0022\u005e\u0034\u0032\u006b\u004c\u0051\u0063\u0060\u007d\u0031\u0031\u0072\u006a\u0070\u0023\u003f\u0068\u006f\u006c\u0033\u006b\u0035\u0040\u0070\u0062\u0028\u0037\u0063\u0058\u003f\u0021\u0028\u0059\u0073\u002f\u0028\u0040\u0070\u0062\u0028\u0037\u0063\u0061\u0035\u004a\u004b\u0047\u006d\u005d\u006a\u0040\u0046\u0021\u003a\u002e\u0073\u004b\u005a\u0064\u0060\u0069\u0033\u004a\u0073\u0032\u0072\u0044\u007d\u0029\u0037\u0066\u0038\u0047\u0043\u006a\u0045\u0039\u0041\u0023\u0050\u0050\u005b\u0036\u0037\u0079\u002c\u0048\u002b\u003c\u0065\u0077\u006f\u005f\u0033\u0021\u0071\u005b\u0031\u0024\u004b\u0053\u0032\u003b\u004e\u004f\u0050\u0038\u0067\u0056\u0078\u0024\u007a\u0036\u0025\u002e\u002a\u0046\u0048\u0022\u006b\u006d\u003f\u0055\u0021\u003d\u0029\u0034\u0025\u0051\u0046\u0052\u004e\u0063\u0039\u0074\u007c\u0057\u0048\u0054\u007b\u0025\u0025\u003e\u007d\u0060\u0054\u006e\u0031\u0030\u002c\u0060\u002b\u0025\u0030\u0062\u007b\u0044\u004a\u0057\u004d\u0045\u002b\u0052\u007a\u0043\u005e\u0060\u0057\u0043\u006f\u002f\u002f\u002a\u0049\u0054\u0033\u0053\u0062\u0028\u0062\u0028\u002a\u002c\u0023\u0030\u0039\u0036\u006c\u002a\u0040\u002c\u0046\u0060\u0032\u007c\u0077\u0052\u006a\u0076\u007c\u0042\u004a\u004c\u0047\u0059\u006d\u006a\u0031\u0056\u0055\u003d\u002c\u0023\u0038\u0035\u0075\u0041\u005b\u006c\u006d\u0021\u0055\u0022\u0050\u007c\u0063\u003e\u0061\u006c\u0058\u0029\u0053\u002a\u007e\u0050\u0022\u0040\u0056\u0054\u002a\u0070\u007c\u0040\u0035\u0041\u0069\u0030\u0035\u0073\u0045\u002f\u007c\u003e\u0065\u005b\u005d\u0036\u0065\u0056\u005b\u0055\u006e\u0026\u0054\u003c\u0034\u0021\u0044\u0022\u002f\u0036\u0028\u0075\u0074\u004f\u005f\u0058\u0033\u0047\u0068\u0035\u0041\u0069\u0030\u0070\u004b\u0028\u0041\u006f\u002e\u0047\u005f\u0063\u0054\u0038\u0025\u0051\u0024\u0048\u002f\u004f\u004b\u0035\u003e\u0062\u0024\u0077\u006a\u0048\u0049\u0031\u0045\u0052\u003e\u003c\u0033\u0041\u0050\u007a\u0075\u0040\u006b\u0025\u007e\u002e\u002c\u004a\u0022\u005f\u0051\u004b\u0033\u0064\u0075\u0069\u0062\u0072\u006d\u003a\u005e\u0055\u007d\u004a\u0022\u007d\u0049\u0074\u0055\u0069\u0064\u0034\u006b\u004e\u0023\u0023\u0078\u0048\u002a\u0032\u003c\u0061\u0037\u0057\u0035\u0028\u002f\u0077\u0048\u0074\u0049\u0038\u0025\u003b\u0051\u0075\u0060\u0023\u0036\u0059\u004f\u004d\u007a\u0044\u0060\u0043\u0061\u0071\u0026\u003e\u0051\u007a\u0060\u0047\u0036\u004a\u0063\u0045\u0043\u0042\u004e\u0042\u0032\u0026\u0041\u0056\u006f\u004d\u0057\u006b\u0072\u0073\u0048\u007a\u002a\u0031\u004b\u0037\u003c\u006c\u002e\u006b\u0072\u0054\u0031\u0029\u0060\u006b\u0071\u0039\u006a\u0039\u0043\u0068\u005e\u007b\u0046\u0066\u0079\u007b\u0054\u004e\u0053\u0068\u0028\u0058\u0041\u003d\u006e\u0057\u005e\u0035\u0062\u006e\u0052\u0059\u0068\u0078\u0040\u0067\u003a\u0061\u004d\u004f\u0044\u0024\u002f\u0024\u0062\u0050\u002e\u003f\u0067\u005d\u006a\u0038\u004f\u0049\u0075\u003f\u0051\u0025\u004f\u0075\u003b\u003b\u0064\u007d\u002b\u007b\u0047\u0032\u0065\u0064\u007b\u0056\u0056\u002a\u005b\u0067\u0021\u0046\u0074\u005f\u0070\u0056\u0021\u0062\u0043\u0062\u0063\u003d\u006e\u006f\u0058\u0059\u0030\u0061\u0049\u0079\u0048\u0063\u0043\u0062\u007b\u002a\u004b\u0065\u0044\u007e\u0071\u0060\u003a\u004a\u0038\u005a\u0028\u002a\u0028\u0045\u006e\u0065\u003f\u0062\u0034\u0077\u0066\u0059\u0063\u006b\u004f\u004a\u004b\u0050\u0062\u0039\u004a\u0054\u0078\u0040\u005d\u006f\u0036\u0028\u0045\u006e\u0065\u003f\u0062\u0044\u0060\u004c\u004a\u0021\u003d\u0060\u004e\u003b\u0068\u005f\u006a\u0075\u0058\u0035\u0072\u0025\u0065\u002c\u0035\u003c\u003c\u003a\u004d\u0059\u003e\u0056\u0075\u003c\u005b\u0023\u002b\u0032\u0072\u0029\u0057\u005d\u007d\u003e\u0072\u002e\u005a\u002a\u0038\u003c\u0051\u003e\u0077\u0024\u006e\u0058\u0035\u0072\u0025\u0065\u002c\u005b\u0069\u006e\u0072\u0037\u003e\u0036\u0076\u0055\u0062\u002e\u006b\u0049\u0075\u003f\u0051\u0025\u004f\u0028\u0067\u005f\u0022\u0077\u0059\u0039\u002b\u0057\u0026\u0023\u0071\u0070\u0067\u004c\u005e\u0043\u0045\u003c\u0074\u006c\u0050\u007d\u007c\u004d\u006e\u003f\u004c\u004e\u0068\u004b\u0062\u0021\u0058\u007b\u0047\u0030\u0031\u003f\u0079\u002e\u0065\u0064\u002c\u0043\u0021\u0022\u005a\u005f\u0073\u0063\u005b\u0031\u006f\u0059\u0076\u002c\u0021\u0052\u0052\u0067\u006b\u004b\u004e\u0056\u0076\u002c\u0063\u0044\u0036\u004d\u0036\u003e\u0026\u0072\u002a\u006a\u007c\u0038\u0062\u0064\u004e\u0029\u003e\u006b\u0065\u002a\u003e\u0026\u0072\u002a\u006a\u0064\u0039\u0031\u003f\u0073\u003d\u0066\u005a\u006f\u003d\u0042\u0030\u005d\u0070\u0067\u0064\u0028\u0079\u0041\u004b\u007e\u0062\u0024\u006e\u0040\u0026\u0031\u0034\u0034\u006c\u002a\u003e\u0026\u0072\u0077\u0054\u0073\u0029\u006e\u006a\u0026\u0057\u0032\u0062\u006d\u002c\u0065\u0021\u0052\u0067\u0067\u005b\u0078\u0037\u006f\u0048\u004a\u002c\u0021\u0066\u003b\u0025\u005a\u0070\u0023\u004e\u0043\u003d\u0039\u0056\u006e\u0065\u004f\u003b\u005b\u0024\u007c\u004d\u002c\u0031\u0048\u0050\u0040\u0024\u0073\u0045\u0042\u0053\u0079\u0070\u002a\u0046\u002c\u0069\u0064\u0048\u004a\u0063\u004b\u005d\u0051\u002a\u007c\u0062\u0025\u0056\u0037\u0050\u0059\u0046\u0032\u0022\u0023\u0025\u0043\u0067\u007b\u0078\u0037\u0040\u0073\u0028\u0022\u003b\u0059\u0046\u0032\u0054\u004d\u0079\u006c\u004e\u003f\u0069\u0030\u005f\u005a\u004b\u003f\u0048\u0066\u003f\u0024\u0047\u002b\u0074\u004a\u0047\u004c\u002f\u0067\u0042\u0072\u0073\u004b\u0056\u003f\u005f\u0046\u0045\u007b\u004e\u0049\u0042\u0062\u0061\u0033\u0065\u004d\u002c\u0047\u007b\u0054\u004e\u0053\u0068\u0028\u0058\u0024\u0067\u0068\u0052\u0030\u006b\u0076\u007e\u003e\u0051\u0055\u004f\u002f\u0067\u0068\u0075\u003c\u0058\u003b\u004e\u003c\u002f\u0078\u0028\u0036\u0052\u003e\u006d\u003b\u0075\u0055\u0030\u0060\u0059\u0072\u004d\u007e\u0061\u0035\u0047\u0059\u0043\u002a\u0028\u0067\u006d\u003c\u007b\u007c\u0048\u0058\u006d\u0047\u0034\u005b\u004c\u004c\u0054\u0049\u0067\u002c\u0040\u0052\u0058\u0056\u0053\u0068\u0058\u002a\u0070\u0064\u005b\u0073\u0030\u0047\u0060\u0058\u005d\u0036\u006c\u0037\u006e\u007a\u0050\u002f\u0062\u002f\u0062\u0054\u007d\u0067\u0053\u006a\u005e\u0070\u003f\u0038\u0051\u0062\u0055\u0041\u003d\u006e\u006e\u0068\u0050\u007c\u0074\u006c\u0032\u0058\u0056\u0053\u0068\u0072\u0038\u007a\u003d\u0026\u0051\u0028\u0039\u0042\u0036\u0069\u002e\u005e\u0055\u004c\u0040\u0075\u0051\u007a\u0060\u003a\u0036\u004e\u007b\u0067\u006b\u0068\u003f\u0032\u005b\u007c\u0041\u0052\u004f\u0050\u0058\u0058\u0031\u0050\u0070\u0055\u0050\u0030\u004b\u0021\u0057\u006b\u0063\u0048\u0025\u0064\u0071\u0075\u003e\u002a\u0031\u0063\u007b\u002b\u006f\u0058\u0058\u0022\u0068\u0054\u0048\u0058\u007e\u0038\u0059\u0033\u0077\u007c\u0057\u0051\u0042\u0078\u0050\u0059\u0037\u0079\u003c\u0031\u0064\u0068\u004e\u0028\u006f\u0079\u0042\u0055\u0075\u0058\u0021\u0028\u004b\u0029\u0063\u0059\u003b\u0063\u003d\u0065\u0021\u0028\u0025\u0022\u0036\u0043\u0045\u002a\u0052\u0037\u0059\u0039\u002b\u004b\u006c\u0069\u0026\u003e\u0074\u003c\u003b\u0072\u003b\u002b\u0067\u005a\u0079\u0077\u006f\u005b\u0052\u0077\u0077\u0055\u006f\u0029\u0065\u0026\u0062\u0046\u0051\u0065\u0037\u004c\u007e\u0038\u006e\u006b\u003f\u007b\u006d\u0035\u007a\u0046\u0048\u0062\u0055\u007c\u0041\u004e\u0068\u0061\u006d\u0076\u0051\u005a\u0062\u007e\u0059\u0025\u003c\u003c\u0075\u0050\u0021\u002b\u003c\u0048\u0073\u003d\u0030\u002e\u0047\u0076\u0029\u0049\u0049\u0021\u003d\u0022\u0045\u0065\u0069\u0044\u0031\u006f\u0076\u003b\u002f\u0037\u002b\u0056\u002c\u0045\u002e\u0066\u0047\u0028\u0028\u004c\u004b\u007a\u005b\u007c\u0042\u0035\u0069\u003e\u0030\u0041\u0063\u003d\u0064\u0074\u003b\u0079\u0058\u0072\u0071\u0049\u0039\u0053\u0030\u0041\u0064\u0052\u002c\u007d\u005f\u002a\u0038\u0031\u0039\u0079\u0052\u0067\u002f\u007b\u0042\u007b\u007a\u0025\u006c\u0050\u004f\u003a\u0065\u005f\u002a\u004f\u0044\u0046\u0072\u002c\u007a\u0021\u004e\u005f\u003f\u0025\u0051\u007c\u003a\u0073\u003e\u0078\u0029\u0032\u005b\u0032\u0061\u004d\u004c\u006c\u002e\u0021\u007d\u0073\u0063\u0063\u0050\u006f\u0022\u0041\u003c\u006c\u0055\u003f\u0061\u006e\u0043\u0042\u006b\u007d\u0055\u0063\u0063\u0050\u006f\u0022\u0041\u006e\u003a\u005a\u0064\u003a\u0025\u007d\u006c\u0063\u0077\u003f\u0055\u0047\u0024\u0039\u0039\u0024\u0042\u0071\u002e\u0039\u007e\u0032\u0058\u005b\u0060\u0052\u0070\u0079\u0024\u005d\u005e\u0048\u003b\u003b\u0063\u007d\u006d\u0044\u0039\u0072\u0045\u0035\u003e\u004e\u0048\u0052\u005b\u003b\u004a\u007e\u006a\u0033\u006c\u007b\u007c\u0048\u0029\u0025\u0062\u0054\u004d\u006c\u0057\u0028\u006c\u0069\u005a\u005a\u0057\u0068\u0068\u006a\u005a\u003a\u006a\u006d\u0058\u005b\u005e\u0063\u003e\u0045\u0060\u006c\u006e\u0066\u006f\u005d\u0066\u0075\u006b\u004e\u0048\u0022\u005b\u0065\u0076\u0066\u0059\u0025\u0075\u0053\u0044\u002f\u0022\u002f\u007d\u0026\u004e\u0022\u0064\u0040\u0060\u0033\u002a\u0049\u0023\u0045\u003a\u0066\u002e\u0031\u003d\u005e\u0039\u0039\u006e\u0063\u006a\u0033\u0039\u007d\u0042\u0050\u0068\u0053\u0051\u0022\u0060\u0076\u0075\u0059\u0066\u0040\u005a\u0046\u007c\u007b\u0065\u007d\u0057\u004f\u003a\u0069\u0040\u0026\u0024\u004b\u0044\u0063\u004f\u0068\u0046\u004b\u0065\u0031\u0071\u0044\u0035\u004d\u0021\u003d\u0069\u0076\u0042\u006c\u0050\u003a\u0058\u002c\u0078\u004e\u0022\u0033\u0039\u0071\u006a\u0053\u0066\u002c\u005b\u0054\u0059\u0040\u0033\u0052\u005b\u0077\u0039\u0024\u002f\u006a\u0050\u0021\u0045\u007a\u0026\u003d\u0064\u004e\u006a\u0066\u006f\u0054\u0069\u0075\u0071\u0036\u006a\u0035\u003c\u0062\u006d\u006c\u0047\u0058\u0051\u0077\u0030\u0021\u0052\u0052\u006f\u006a\u002b\u0062\u0052\u0068\u0070\u0073\u004b\u0038\u0043\u007e\u0037\u003f\u0056\u0041\u0030\u006c\u003a\u0041\u006f\u0023\u002a\u002e\u0051\u0060\u004d\u0046\u0065\u0031\u0043\u004c\u004c\u0068\u005b\u005b\u0049\u0048\u002c\u0034\u0077\u0059\u007e\u003f\u0071\u0043\u003c\u0034\u002e\u0072\u0055\u0059\u0051\u0070\u007c\u0041\u0030\u0039\u0054\u0032\u0025\u006d\u006d\u005e\u0048\u007a\u0069\u006c\u0043\u004c\u004c\u0068\u005b\u005b\u0049\u004c\u006c\u0049\u0052\u0079\u005f\u0036\u0033\u0029\u0065\u002c\u007a\u003d\u0026\u0051\u0028\u0039\u006c\u0031\u007e\u003f\u0062\u006a\u0056\u0074\u003f\u003e\u004f\u0065\u0068\u0062\u0075\u0069\u0071\u0050\u006f\u0076\u004d\u007c\u0058\u0052\u006f\u0051\u0022\u0071\u006b\u0073\u0073\u0052\u0040\u0043\u0066\u0040\u004e\u006d\u0038\u006f\u005b\u0056\u0039\u0061\u0069\u006a\u0022\u0042\u0028\u006e\u0052\u0064\u0063\u0053\u007a\u0025\u0049\u0069\u0069\u0051\u0030\u003b\u0046\u002a\u006b\u0026\u005f\u0042\u0050\u005d\u004b\u002b\u0051\u003d\u0040\u005b\u0058\u0047\u0041\u005e\u0074\u0045\u0074\u005b\u006e\u005a\u0071\u005f\u0047\u0026\u0048\u007a\u0041\u0041\u003a\u007e\u0057\u0048\u0031\u0067\u005f\u0076\u0025\u002e\u005f\u0058\u003a\u006b\u007e\u0049\u0048\u0074\u0050\u003c\u0034\u0053\u0079\u0046\u0061\u0038\u0079\u002e\u002f\u0061\u0058\u006f\u006e\u0070\u0063\u0077\u007b\u0072\u003e\u0060\u0076\u0059\u0032\u002a\u002f\u006d\u0040\u002e\u0037\u0068\u0023\u005f\u0021\u0036\u006d\u007c\u006f\u0037\u0041\u0044\u0065\u0072\u0055\u0064\u0076\u005b\u0075\u004c\u005e\u0023\u006c\u0046\u0034\u0022\u0070\u0033\u005f\u0032\u006f\u0067\u0067\u0059\u0024\u0061\u0029\u0058\u007c\u0075\u007c\u0064\u004e\u003e\u0035\u003d\u0045\u003d\u0051\u004c\u0039\u0062\u0047\u0023\u007c\u0062\u0072\u0079\u0021\u007d\u0079\u0062\u002e\u0035\u006d\u0059\u0037\u0038\u0065\u007a\u006b\u004f\u0029\u0073\u0056\u0025\u004b\u0071\u0050\u0070\u003d\u0077\u004f\u006d\u0049\u0057\u006f\u0046\u0074\u002b\u0045\u004b\u004d\u0028\u0060\u005b\u0067\u003b\u002b\u0052\u0077\u0061\u0046\u003b\u007a\u003e\u004d\u006d\u0059\u0052\u003c\u0043\u0037\u0042\u0052\u0035\u0039\u004d\u0075\u0034\u0024\u0073\u002c\u0026\u0038\u0077\u0076\u0028\u0023\u0043\u0041\u004a\u004b\u0061\u0022\u0056\u0038\u006e\u0042\u0072\u0046\u0071\u0050\u0024\u005f\u0064\u0058\u0034\u0044\u006b\u0051\u0065\u0074\u0032\u006b\u0039\u0067\u0057\u0053\u003e\u0040\u0034\u0058\u0052\u0052\u006b\u0051\u004f\u0029\u0048\u003d\u0051\u002a\u0065\u0062\u0060\u0039\u006a\u003d\u0051\u0070\u006a\u0021\u003b\u0073\u0031\u0057\u004c\u006d\u0051\u0031\u0034\u0031\u0072\u003d\u0056\u005f\u004d\u003a\u0046\u0037\u0053\u0061\u003f\u0046\u0077\u0067\u002b\u002f\u0065\u0052\u0063\u0045\u004b\u007c\u0054\u0038\u0025\u0042\u007a\u006c\u002c\u0054\u006f\u0034\u0036\u003b\u0043\u0063\u0038\u0036\u003f\u0029\u0021\u0045\u004e\u0059\u0054\u0035\u0047\u005f\u0034\u006e\u0069\u006a\u0068\u007c\u007d\u002b\u0076\u006b\u003f\u0046\u0077\u0067\u0051\u0067\u0033\u0055\u0030\u0049\u002c\u002f\u007d\u002b\u0061\u006b\u0037\u0059\u005d\u0066\u0021\u004e\u0054\u0079\u0030\u0049\u0058\u0054\u0022\u002b\u0036\u0053\u0030\u0059\u0054\u0035\u0053\u0037\u003e\u003b\u0030\u0024\u005a\u006f\u004f\u0029\u0073\u0044\u003b\u0021\u0043\u0062\u0025\u003a\u0067\u0026\u006d\u004d\u0077\u0069\u0029\u002f\u0033\u0052\u0022\u0036\u0040\u003e\u003d\u0026\u0026\u006c\u0034\u0039\u0035\u0026\u005f\u0051\u0045\u004a\u0054\u0041\u0069\u0035\u0068\u0073\u0073\u0035\u0070\u002f\u0056\u007d\u005a\u0028\u002c\u006e\u003f\u0031\u0077\u0064\u0069\u0059\u007a\u0067\u003f\u004f\u0063\u0069\u003d\u003d\u0046\u0034\u0069\u0030\u0069\u005a\u003a\u0076\u0064\u002a\u0077\u0060\u006e\u007b\u0045\u002e\u003c\u0052\u0071\u0029\u0029\u0042\u005e\u0073\u0063\u0030\u0046\u002e\u006e\u0062\u0025\u0034\u0070\u0043\u0024\u0031\u004e\u002f\u0065\u0077\u0050\u0036\u0056\u004f\u003b\u0026\u0051\u0026\u0051\u0067\u003a\u0070\u0058\u0065\u0023\u004b\u0050\u0045\u0046\u003f\u004b\u004e\u0070\u006a\u004f\u004d\u0052\u0039\u0064\u0059\u0021\u002f\u0072\u005b\u006c\u0074\u0057\u0021\u0028\u003b\u006f\u0060\u0054\u007b\u0041\u004d\u002c\u003e\u0076\u0025\u007b\u0032\u0062\u0048\u0035\u0077\u0021\u0052\u0031\u0032\u0022\u0024\u0039\u0063\u005a\u0065\u0043\u0079\u004a\u002f\u006a\u0053\u006b\u0074\u003c\u0037\u0069\u0024\u004a\u0063\u007a\u005d\u007b\u0035\u007e\u002f\u0031\u0077\u005d\u003f\u006b\u007e\u0053\u0050\u0033\u0021\u0045\u005f\u0029\u005a\u005a\u0066\u0048\u004f\u0049\u005d\u004d\u003d\u007b\u0073\u003e\u004b\u0026\u003b\u0057\u0023\u002f\u0041\u003a\u0060\u0040\u0021\u003d\u0022\u0045\u0033\u0060\u0052\u003c\u0041\u0038\u002b\u002a\u005d\u0023\u002f\u0023\u0070\u003b\u0051\u007a\u0060\u0077\u0072\u005d\u0053\u0040\u005a\u0074\u0026\u0073\u005b\u004f\u003b\u0026\u0051\u0026\u0051\u0067\u004e\u002e\u002e\u0023\u007c\u002f\u0073\u0032\u004d\u0025\u006d\u002e\u007b\u006c\u0060\u004e\u0061\u0025\u003c\u007a\u0034\u0042\u0069\u004e\u0046\u0079\u0037\u007a\u006f\u0066\u006c\u0062\u0050\u003a\u0024\u004f\u004a\u0048\u0060\u0040\u002f\u0046\u0058\u0053\u0034\u0060\u006f\u0026\u0031\u004c\u0047\u0029\u006c\u0077\u003d\u005e\u005b\u0045\u002e\u0067\u003c\u0045\u0078\u006a\u0052\u007e\u0045\u007c\u0051\u005b\u0036\u0032\u0054\u0029\u0023\u003a\u002c\u004b\u0052\u007a\u0033\u007c\u0066\u0042\u0065\u005b\u007a\u005a\u0035\u0044\u0061\u006f\u007b\u0023\u0066\u0078\u0071\u005a\u0035\u005a\u002e\u003a\u006c\u0049\u0072\u0063\u005b\u0048\u0034\u0047\u0039\u0068\u0033\u0037\u004a\u002f\u0055\u007b\u006a\u003e\u004c\u0074\u005b\u0031\u0071\u006a\u005e\u0067\u002a\u0030\u0025\u0046\u0033\u0022\u0030\u0038\u006f\u002c\u0050\u0062\u005d\u003d\u006d\u0071\u006a\u005b\u0034\u0043\u0034\u0064\u007d\u0058\u004a\u004e\u0035\u0045\u003c\u004b\u0071\u004f\u002b\u0051\u0025\u0057\u006f\u0049\u0045\u0022\u0044\u004d\u0064\u005e\u0065\u0023\u0051\u005e\u0023\u005e\u0038\u002f\u002a\u0025\u004e\u0041\u0025\u003b\u0049\u0063\u005b\u0048\u0034\u0047\u0039\u003b\u0036\u0077\u0023\u003d\u0063\u002a\u0066\u002e\u004e\u0071\u0048\u0030\u0047\u0036\u0046\u0071\u0074\u005f\u007e\u0032\u0036\u006a\u0059\u0058\u004d\u0064\u0047\u0052\u0074\u0030\u0034\u006b\u0073\u0031\u0065\u0069\u0048\u0077\u003c\u003b\u0072\u007e\u0034\u006f\u0040\u0066\u002f\u0037\u0021\u007c\u004c\u0030\u004a\u004e\u003b\u0067\u0078\u0051\u0057\u0023\u0029\u0068\u0060\u0042\u006e\u0071\u0052\u0042\u006e\u0030\u002a\u007c\u0057\u003c\u0045\u0044\u0038\u0065\u002a\u003d\u0033\u0046\u0057\u0031\u0035\u005e\u0062\u0052\u0073\u006e\u0033\u0069\u007c\u0057\u004e\u0038\u007d\u0062\u0040\u0064\u0052\u0072\u0066\u003b\u0045\u0046\u0057\u0070\u0057\u0056\u0067\u005e\u0047\u0063\u005b\u0048\u0034\u0047\u0039\u0068\u0033\u0041\u004d\u0038\u0079\u003f\u002c\u005a\u0039\u0071\u0022\u002e\u0036\u007e\u004a\u006d\u006d\u003e\u004f\u0070\u004c\u0053\u0029\u0036\u0025\u0060\u0077\u0062\u007d\u0034\u004d\u0062\u0053\u005a\u002a\u007e\u0043\u0037\u003e\u0044\u0064\u002b\u0078\u006e\u006d\u0035\u0033\u0070\u0050\u0050\u003b\u0039\u0026\u0070\u0042\u005f\u0021\u005d\u0028\u003d\u0042\u0071\u0030\u005f\u0057\u0056\u002a\u0063\u004f\u006a\u0048\u0046\u0029\u0034\u0033\u007e\u003a\u005b\u007a\u0022\u0068\u007d\u0064\u003f\u002e\u007b\u0066\u0065\u0078\u006f\u0077\u0070\u005b\u006f\u0032\u002b\u0068\u0066\u0053\u0050\u003e\u0039\u003b\u0063\u0028\u0025\u0060\u007c\u007e\u004c\u006f\u0046\u0069\u0044\u006f\u0063\u0059\u006f\u0073\u0062\u0053\u004c\u003b\u006f\u0043\u0025\u005a\u0051\u0058\u0055\u0067\u0074\u0065\u0078\u0030\u0035\u0026\u0065\u0050\u0058\u0072\u0071\u0049\u0039\u005b\u0036\u006c\u0051\u006f\u002e\u0062\u0060\u005d\u0025\u0073\u0061\u0043\u0033\u0036\u0028\u0052\u0043\u0025\u0035\u0064\u003b\u0060\u004d\u0036\u002e\u0077\u0054\u002b\u0041\u0071\u002a\u006f\u0047\u0036\u0042\u0030\u0025\u002a\u0042\u0066\u007c\u0067\u0078\u003e\u0057\u0065\u0069\u003d\u006b\u0038\u007a\u0034\u006f\u0062\u0041\u0029\u0058\u0069\u004e\u0029\u005e\u006f\u0071\u006c\u0025\u002c\u0071\u0051\u0030\u0047\u0036\u0033\u003e\u0061\u005a\u0071\u0054\u002b\u0041\u0071\u0075\u004b\u0060\u0051\u0036\u005b\u0043\u002e\u0052\u0034\u0022\u0069\u0058\u0060\u0054\u004e\u007d\u007e\u006f\u0060\u004c\u007a\u0067\u0077\u0037\u002e\u0028\u0038\u0072\u005f\u0032\u0068\u0059\u005b\u004a\u0063\u0044\u0055\u0062\u0031\u0025\u003a\u0043\u0037\u006d\u007e\u005f\u004b\u005b\u003e\u0043\u0063\u006b\u007a\u0022\u004e\u0046\u0068\u006b\u0065\u007d\u0062\u0044\u0057\u0041\u002e\u007c\u006b\u0025\u0031\u0043\u0050\u0031\u002e\u0069\u0033\u005e\u0074\u004f\u0055\u0050\u0031\u0060\u0046\u003b\u0026\u0057\u0021\u003c\u0031\u004e\u0053\u007e\u004d\u0042\u0043\u004c\u007a\u0079\u0075\u0034\u005b\u003d\u0076\u0029\u006b\u005f\u0059\u0038\u0073\u0054\u0059\u002c\u0029\u0068\u0041\u003e\u005b\u005b\u0050\u0070\u0042\u005b\u003d\u0076\u0029\u006b\u004a\u0030\u0074\u0055\u005b\u0076\u0054\u0023\u006b\u0046\u0026\u0057\u0021\u0069\u005e\u0026\u004f\u0037\u005b\u0074\u0038\u005b\u0024\u0075\u0045\u006b\u0037\u0044\u0065\u0064\u006f\u0059\u002c\u0022\u0062\u005e\u005f\u0038\u003a\u0068\u0040\u006f\u0057\u0021\u0028\u003b\u006f\u0060\u0022\u002e\u0037\u0065\u0029\u0064\u0054\u004c\u0043\u0025\u0035\u0064\u005b\u0055\u0047\u0036\u0059\u0031\u007d\u0048\u0062\u0033\u0060\u004e\u0036\u002f\u0054\u0029\u0021\u002e\u0078\u0073\u0044\u0055\u005b\u0036\u0031\u0046\u0025\u004c\u0054\u0033\u003d\u0026\u0051\u0023\u0043\u003a\u0031\u0041\u0071\u0051\u0022\u0051\u0075\u0040\u0031\u0071\u0051\u0030\u006c\u0033\u003c\u0024\u003c\u0037\u0026\u003f\u0056\u002c\u007e\u003d\u005a\u0051\u003b\u0068\u0075\u002e\u0068\u0064\u0023\u004d\u003a\u0024\u0047\u006c\u007a\u0063\u0073\u0029\u002c\u0077\u0066\u0075\u0070\u0064\u0051\u005f\u0056\u002e\u0078\u0054\u004e\u0055\u003a\u0051\u0075\u0073\u0056\u002e\u002a\u0078\u0059\u0070\u0077\u0064\u0077\u0064\u003e\u0057\u0039\u004a\u004d\u0049\u006c\u0032\u0077\u002e\u0036\u0047\u002a\u0025\u0024\u007c\u0033\u005f\u0038\u004d\u002b\u0049\u0022\u006b\u0071\u0037\u002a\u0062\u0030\u0057\u0031\u002f\u0047\u0029\u0023\u0062\u006d\u003e\u0068\u004c\u0078\u0044\u0060\u0037\u0048\u0079\u0062\u0044\u002a\u0062\u003a\u0059\u005f\u0072\u007d\u002a\u0043\u0078\u003c\u005a\u007e\u0076\u0048\u0035\u0047\u0045\u0045\u0038\u0076\u002e\u006d\u0026\u0052\u003f\u0067\u0031\u0046\u0032\u0062\u007b\u006a\u003a\u0023\u0026\u0075\u005a\u0040\u0053\u0023\u0055\u0057\u0053\u0049\u004d\u002e\u0048\u007b\u0035\u0052\u0028\u004a\u0047\u002c\u0023\u0035\u002f\u0022\u0031\u005b\u004e\u0079\u002a\u007a\u0057\u005a\u006b\u0077\u0053\u003d\u0041\u0024\u005a\u0041\u006a\u004b\u0065\u0030\u003a\u003e\u0060\u0039\u006d\u003d\u0022\u005e\u0028\u0024\u0065\u0023\u002f\u0074\u0052\u0071\u003b\u004d\u0026\u0029\u0049\u002a\u0040\u0078\u002f\u0054\u0064\u006d\u0056\u0033\u004a\u0028\u0021\u0034\u007d\u007d\u006a\u003b\u003c\u005a\u0060\u0036\u003b\u0060\u006c\u0068\u005b\u003e\u0031\u0059\u0034\u0070\u0066\u0076\u0040\u006f\u0029\u0071\u0069\u0073\u0046\u0057\u003d\u0079\u0058\u0039\u005b\u0067\u0021\u003d\u0043\u0051\u0054\u0069\u0066\u0053\u0074\u0037\u0065\u0077\u0029\u0064\u002e\u003a\u0047\u002e\u0035\u006d\u0052\u004a\u003b\u0042\u004f\u0073\u0040\u0059\u0038\u002e\u0077\u005b\u003e\u0043\u0033\u0051\u0029\u005a\u0060\u004b\u0042\u004d\u0040\u0021\u003a\u0041\u0064\u0059\u0028\u0050\u003d\u0021\u007e\u0045\u003c\u0068\u0051\u002e\u0068\u0048\u003d\u0076\u006d\u0032\u0045\u005e\u0056\u0024\u0053\u006c\u0043\u002b\u003f\u0036\u007a\u003d\u0026\u0051\u0028\u0039\u006c\u0031\u007e\u003f\u0062\u006a\u002f\u0026\u004b\u0079\u0023\u0065\u0068\u0062\u002c\u0056\u007e\u0047\u005d\u0076\u0034\u0021\u003d\u0022\u0045\u0040\u007e\u005d\u007d\u0022\u0045\u0063\u0030\u006a\u0049\u0075\u0073\u0023\u0076\u0059\u0029\u0062\u002b\u0057\u0063\u0042\u0023\u0043\u006c\u0031\u004c\u002f\u007d\u0024\u0070\u005b\u0063\u0034\u0069\u0030\u002e\u0073\u002e\u0037\u0026\u0021\u005b\u007c\u0048\u0033\u0048\u003b\u002f\u0050\u007a\u007a\u003a\u003d\u0031\u0029\u006d\u0026\u0048\u0033\u002b\u0052\u0043\u005f\u0028\u004c\u0034\u0053\u0068\u004a\u005e\u004b\u0065\u0041\u0051\u0023\u0072\u006f\u0067\u0042\u0075\u003d\u0053\u0043\u002b\u006f\u007e\u0026\u0062\u003a\u002e\u007c\u006b\u003b\u0024\u0047\u0030\u006e\u0074\u0030\u003c\u005e\u0070\u0079\u0039\u0045\u0068\u0047\u0036\u0075\u002b\u0073\u0065\u0076\u0042\u0071\u0069\u0076\u0067\u0035\u006f\u002b\u006f\u006c\u0078\u0043\u0025\u005a\u0051\u0058\u0055\u0052\u002e\u0058\u004a\u003f\u0026\u0054\u0072\u006c\u005a\u0055\u0074\u005b\u005d\u005a\u007e\u004c\u003d\u007e\u005b\u0059\u0044\u002a\u0071\u0025\u004c\u0052\u0056\u0071\u0049\u0065\u0061\u004b\u0061\u004d\u0064\u003f\u0057\u002e\u002a\u0051\u0047\u007b\u0038\u0051\u004b\u0051\u004d\u0064\u003f\u002a\u005b\u0039\u0033\u0025\u0029\u004b\u007e\u0041\u0053\u007d\u005e\u0022\u0073\u006e\u005e\u0051\u006e\u0044\u0053\u007c\u002b\u004d\u0069\u007d\u0077\u0064\u005d\u0069\u0030\u0036\u0054\u0072\u006c\u0030\u007d\u0031\u002e\u0061\u005b\u0038\u006f\u005e\u0071\u004f\u006c\u0036\u006b\u0074\u002e\u0064\u0072\u0024\u0052\u0045\u0070\u0049\u005d\u006e\u004f\u003e\u0053\u004a\u006f\u0047\u0052\u0042\u0070\u0025\u004c\u0052\u006e\u005e\u003e\u0045\u0059\u0063\u0037\u003e\u0028\u0023\u0077\u002b\u002e\u0037\u0031\u002c\u0050\u0042\u0023\u003c\u0056\u0068\u0023\u0065\u0022\u0022\u0025\u003f\u002e\u0037\u006e\u0026\u0030\u0023\u003f\u0023\u0054\u0063\u0075\u0040\u0031\u0071\u0051\u0030\u0047\u0036\u0045\u0055\u0061\u0049\u007c\u0064\u0063\u005b\u007e\u0045\u0074\u0043\u002c\u0036\u0070\u007a\u0078\u006c\u0025\u006e\u0062\u0025\u0034\u0070\u0043\u004d\u0036\u0068\u004d\u004d\u005e\u0025\u0079\u0039\u0035\u0035\u0067\u004a\u0076\u0042\u002f\u002f\u003a\u0028\u003d\u0042\u0071\u0030\u005f\u0026\u0036\u0045\u0063\u0038\u0074\u0073\u0057\u0036\u003e\u0078\u0062\u004e\u0050\u0058\u0072\u0071\u0049\u0039\u0053\u0030\u0059\u004f\u0023\u0022\u0068\u0033\u0077\u003f\u0036\u0057\u0042\u0071\u007c\u0055\u0039\u003b\u0064\u0053\u004d\u0065\u003d\u0076\u0041\u003d\u004e\u0079\u0053\u005e\u0044\u0052\u0042\u0061\u004c\u002c\u0042\u006c\u0021\u0048\u0044\u004a\u004b\u0067\u0031\u0023\u0065\u005a\u0036\u003a\u0078\u004a\u0054\u0077\u0057\u007d\u0021\u0074\u0053\u0028\u003c\u0046\u0076\u004f\u0039\u0068\u0021\u003d\u0022\u0045\u006f\u0060\u006c\u0031\u004a\u0053\u002f\u0064\u002b\u006a\u0062\u0071\u0022\u002e\u0054\u0051\u0072\u0061\u0064\u006d\u004f\u0068\u0049\u0077\u0056\u0033\u0047\u0038\u004b\u0071\u0060\u0055\u0051\u006e\u0057\u005f\u003c\u0029\u007d\u0070\u0078\u0021\u0074\u0061\u0057\u0044\u0073\u0049\u0031\u0057\u006c\u006c\u0025\u006b\u0074\u0026\u006d\u0033\u0078\u0062\u0052\u004a\u0046\u0054\u0036\u0021\u003d\u0022\u0045\u002e\u0038\u0074\u002e\u0021\u003e\u0049\u005d\u0045\u007c\u0058\u0059\u0066\u006f\u0060\u0042\u0036\u0038\u0053\u003c\u0024\u006b\u004d\u004e\u0041\u005a\u0040\u0051\u0079\u003e\u004a\u005e\u0072\u0070\u0025\u0061\u0048\u0079\u0058\u0070\u0045\u007e\u007e\u0065\u0058\u0047\u0051\u0042\u0078\u0023\u0031\u007e\u003f\u0062\u006a\u002f\u0026\u004b\u0079\u0023\u0065\u006c\u0034\u0049\u0039\u0067\u003e\u0034\u0046\u004c\u004d\u0021\u005b\u0022\u0032\u0068\u005f\u004b\u0036\u005b\u003c\u0060\u0042\u0034\u0042\u0071\u003e\u0025\u002e\u002a\u007e\u0049\u0060\u0042\u0034\u0042\u0071\u003e\u0041\u0033\u0050\u0055\u0029\u003a\u006f\u0022\u0076\u002e\u0046\u007c\u0048\u007d\u0077\u0036\u003b\u003a\u0063\u003d\u0021\u0034\u004e\u005d\u007e\u007b\u0028\u0064\u006b\u0044\u0057\u0034\u0065\u0040\u0054\u0071\u0071\u0074\u004e\u0032\u004f\u0036\u0079\u0067\u005b\u005d\u0078\u004e\u0056\u0079\u005a\u0066\u0023\u0057\u0076\u0035\u0062\u0037\u0069\u0033\u0069\u0050\u007e\u0023\u0045\u0061\u0049\u0060\u006b\u004a\u0025\u0051\u0042\u0045\u0074\u0055\u0030\u0079\u0076\u0042\u006a\u0065\u003b\u0058\u0043\u0022\u0055\u0058\u006b\u0077\u0065\u0073\u0059\u0034\u0028\u005d\u003d\u0070\u004f\u0026\u002a\u0075\u0077\u006d\u0063\u0022\u003c\u0076\u002f\u003f\u004b\u0079\u0046\u0034\u0047\u003b\u002a\u0043\u005d\u0058\u0049\u007b\u005f\u0073\u0076\u0044\u0068\u0040\u006e\u0079\u0061\u0039\u004c\u0035\u004c\u004a\u0050\u0044\u0073\u0039\u006a\u0042\u0077\u0072\u0021\u005e\u0025\u0076\u004a\u0074\u0058\u0070\u005e\u0069\u0051\u0046\u0043\u004a\u004a\u0040\u0031\u002a\u005a\u004f\u004b\u004e\u002c\u0072\u006f\u005e\u007a\u0041\u003a\u0058\u0055\u0065\u007e\u0074\u0038\u003c\u0025\u003c\u002c\u002e\u004c\u005d\u007a\u0021\u006b\u0066\u003e\u004e\u0068\u007c\u006b\u003b\u004d\u0051\u0057\u0043\u007d\u006c\u002e\u0065\u0077\u0070\u0038\u0045\u003c\u006d\u0047\u003b\u002a\u0043\u005d\u0058\u0047\u007a\u0050\u0076\u004b\u005b\u0077\u0060\u004e\u0055\u004a\u0022\u003c\u007e\u003a\u003f\u0070\u0022\u0040\u004e\u004b\u007b\u003d\u0073\u006f\u0025\u0025\u0024\u0040\u0066\u0073\u0044\u004e\u003b\u0062\u0051\u0038\u007e\u0054\u007b\u0062\u0065\u004c\u003b\u0036\u0057\u002c\u0071\u0075\u0063\u0077\u004c\u0035\u006a\u004a\u0048\u0064\u004d\u0046\u0039\u0069\u002b\u0072\u0042\u006c\u005a\u002c\u0047\u007e\u0034\u003c\u0077\u0065\u0039\u0077\u0050\u0070\u006e\u0040\u003d\u005e\u0043\u007a\u0050\u0055\u0044\u007a\u006b\u003a\u0078\u006f\u0028\u002a\u0061\u005e\u0074\u0041\u0076\u0077\u006d\u0063\u007b\u005f\u0022\u003c\u0057\u0053\u003d\u003b\u004c\u0072\u0022\u004b\u002f\u002c\u0025\u0023\u0044\u007a\u006b\u003a\u0035\u0057\u005a\u0068\u007c\u0022\u0060\u002e\u0076\u0045\u0028\u0044\u0058\u0039\u003d\u007c\u006b\u003b\u004d\u0051\u0063\u0048\u0060\u002b\u005f\u0040\u0049\u0051\u0065\u005e\u0069\u0051\u0044\u0077\u004c\u0047\u003a\u0037\u0031\u0055\u0031\u002a\u004e\u004f\u0025\u004c\u006a\u0067\u0058\u004e\u0029\u0077\u006f\u003e\u0072\u003a\u006c\u0031\u0070\u0045\u0045\u003a\u003e\u0029\u007d\u006c\u0079\u007e\u0048\u0054\u0047\u005f\u0072\u0039\u006b\u0025\u003f\u007d\u004d\u0051\u0031\u0068\u0064\u005a\u0051\u002f\u0024\u0079\u0029\u0064\u0069\u006a\u007b\u0026\u0069\u0023\u0076\u0048\u002b\u0065\u0071\u003f\u0038\u007e\u005d\u004e\u003b\u0069\u0051\u006c\u0069\u0044\u007a\u0076\u0035\u0071\u0075\u0063\u0077\u004c\u0035\u006a\u004a\u0048\u0064\u004d\u0046\u0039\u0069\u002b\u0072\u0042\u006c\u005a\u002c\u0038\u0043\u004a\u0047\u003a\u007c\u0028\u0067\u005a\u0068\u0029\u005e\u0060\u002e\u0076\u0045\u0042\u0052\u006a\u0067\u0058\u004e\u006a\u0048\u004a\u004a\u0040\u0031\u007c\u0075\u005b\u0024\u0059\u0041\u0053\u005e\u002f\u002c\u0037\u0037\u0045\u004c\u002f\u0021\u0047\u0059\u006a\u0069\u0051\u006c\u0069\u0044\u007a\u007c\u0060\u0036\u004b\u0022\u0029\u0064\u0035\u006e\u007a\u0032\u006e\u004d\u0031\u0076\u0047\u0057\u0035\u0057\u003f\u0067\u0075\u0038\u0023\u004f\u006e\u0068\u0077\u0059\u0047\u0057\u0035\u0057\u003f\u0067\u006c\u0031\u006d\u0059\u0065\u0045\u0060\u005e\u0034\u0051\u0022\u007d\u0031\u0036\u0050\u004e\u0075\u006f\u0071\u0041\u0058\u0031\u006a\u003f\u007d\u0032\u0077\u0063\u0057\u002c\u0050\u004e\u0075\u006f\u0071\u0041\u0065\u0067\u0042\u0060\u0041\u0056\u0024\u0079\u007c\u004c\u003f\u003f\u004b\u004e\u002f\u0022\u0052\u0074\u0047\u0058\u0078\u0035\u0050\u006b\u0054\u0038\u0075\u0022\u002f\u0023\u0023\u0070\u0068\u0063\u0059\u0045\u007d\u0034\u0021\u002c\u0079\u0066\u0034\u0074\u0055\u0048\u006e\u007b\u006c\u002b\u0060\u0063\u0079\u006e\u003f\u0043\u006b\u007e\u006a\u0047\u0029\u0061\u0023\u0057\u0057\u004a\u0067\u0038\u004a\u0043\u0041\u007a\u0066\u0040\u0052\u0075\u0051\u0067\u004e\u0024\u0077\u0065\u006b\u0047\u007e\u0034\u0073\u0079\u002c\u0036\u0062\u0055\u0068\u0049\u0037\u003c\u0060\u0074\u0061\u0031\u0033\u007e\u0034\u0073\u0026\u0023\u007a\u0077\u0066\u004d\u002e\u003b\u006c\u0078\u003a\u0063\u007c\u0048\u0037\u0074\u0052\u004f\u0064\u0036\u0044\u006e\u0023\u0056\u003d\u004f\u002e\u003b\u0037\u0032\u0021\u0037\u0035\u0047\u0073\u0053\u006f\u0063\u006d\u0022\u004d\u0074\u006e\u0075\u006a\u0067\u0058\u004e\u006a\u0048\u0037\u007a\u004f\u006f\u0021\u003a\u0067\u0041\u0022\u0022\u0074\u0074\u0071\u006c\u0030\u0026\u006b\u006c\u0056\u0033\u0049\u0074\u002c\u0044\u0040\u0033\u004b\u0023\u0043\u0030\u0038\u002c\u0052\u005b\u005a\u0031\u006c\u0067\u0060\u0062\u002b\u0048\u005d\u006f\u006c\u004f\u006c\u006f\u003a\u0066\u006e\u004e\u0049\u004c\u004d\u0054\u0076\u005e\u0021\u0024\u0054\u002c\u0024\u0041\u0037\u0074\u003c\u0028\u0079\u003c\u003b\u0057\u0036\u0042\u0046\u004f\u0036\u004b\u0031\u0041\u0068\u0025\u0049\u0031\u0033\u0055\u0039\u0054\u0051\u0043\u0048\u003e\u007a\u0061\u0036\u0046\u0072\u0046\u0070\u0047\u0025\u0044\u0026\u0053\u007e\u0044